class Solution {public:long long solve(int n,vector<vector<int>>edges){if(n<2)return 0;vector<int>p(n);iota(p.begin(),p.end(),0);function<int(int)>find=[&](int u){while(p[u]!=u){p[u]=p[p[u]];u=p[u];}return u;};sort(edges.begin(),edges.end(),[](auto&a,auto&b){return a[2]<b[2];});long long total=0;int joined=0;for(auto e:edges){int a=find(e[0]),b=find(e[1]);if(a!=b){p[a]=b;total+=e[2];if(++joined==n-1)return total;}}return -1;}};